const ARTICLES = [
  {id:1, cat:"delhii", title:"Днепр хотын төмөр замын буудалд дроноор цохилт өгч, 14 хүн амиа алдлаа", titleEn:"Drone strike on Dnipro railway station kills 14 people", time:"1 цагийн өмнө", timeEn:"1 hour ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Dnipro_railway_station%2C_Dnipro%2C_Ukraine%3B_07.08.19_(2).jpg?width=1000", text:"Украины Днепр хотын төв төмөр замын буудалд пүрэв гарагийн өглөө Оросын тийрэлтэт хөдөлгүүртэй дрон цохилт өгч, дор хаяж 14 хүн амиа алдаж, 10 хүн шархадлаа. Төрийн төмөр замын «Укрзализныця» компанийн мэдээлснээр, дрон Запорожье чиглэлд явах гэж байсан зорчигч тээврийн галт тэрэг зогсож байсан тавцан дээр унасан байна. Агаарын довтолгооноос сэрэмжлүүлэх дохио зарлагдсан байсан ч хүмүүс тавцан дээр байсан гэж компани мэдээллээ.\n\nБүс нутгийн захирагч Александр Ганжа эхэндээ 13 хүн нас барж, 5 хүн шархадсан гэж мэдээлсэн бол хожим нь нас барагсдын тоо 14 болж, шархадсан хүний тоо 10 хүрсэн байна. Шархадсан хүмүүсийн дунд биеийн байдал нь хүнд байгаа 11 настай хүү байгаа гэж мэдээллүүд дурджээ. Мөн өдөр Чернигов хотод хоёр өсвөр насны хүүхэд зэрэг хоёр хүн амиа алдаж, 23 хүн шархадсан бол Кременчук хотод орон сууцны барилгад өгсөн цохилтоор гурван хүн нас барсан байна. Ингэснээр тухайн өдөр улс даяар дор хаяж 19 хүн амиа алдсан тооцоо гарч байна.\n\nЕрөнхийлөгч Володимир Зеленский энэ халдлагыг «аймшигт» гэж нэрлэж, холбоотнуудаа Оросын эсрэг «шударга бөгөөд шийдэмгий» арга хэмжээ авахыг, тэр дундаа хориг арга хэмжээг чангатгахыг уриаллаа. Тэрбээр Оросын эрчим хүч болон зарим олигархуудад ногдуулсан хоригийг цуцалснаас хойш ийм халдлагууд үргэлжилж байна гэж онцолсон байна. Европын Комиссын Ерөнхийлөгч Урсула фон дер Ляйен халдлагыг «утгагүй бөгөөд ялгаваргүй» гэж нэрлээд, түрэмгийлэгчид дарамт шахалт үзүүлэх ёстой гэж мэдэгджээ.\n\nЭнэ халдлага нь АНУ-ын тусламжтайгаар зуучилсан хүмүүнлэгийн эвлэрэл Херсон мужийн Олешки хотод хэрэгжиж байх үед болсон байна. Москвагийн мэдэгдсэнээр, зургаан өдрийн эвлэрэл нь зөвхөн Херсон мужид хамаарна. Украины Ерөнхий сайд Сергей Корецкий Оросыг энгийн иргэдийг зориуд онилж байна гэж мэдэгдсэн бол Москва үүнийг няцаадаг.", textEn:"A Russian jet-powered drone struck the main railway station in the Ukrainian city of Dnipro on Thursday morning, killing at least 14 people and wounding 10 others. According to the state railway company Ukrzaliznytsia, the drone hit a platform where a passenger train bound for Zaporizhzhia was standing. The company said people were on the platform despite an air-raid alert having been issued.\n\nRegional governor Oleksandr Hanzha initially reported 13 dead and five wounded; the toll later rose to 14 dead and 10 wounded. Among the wounded is an 11-year-old boy reported to be in serious condition. On the same day, two people, including two teenagers, were killed and 23 wounded in Chernihiv, while three people died when an apartment building was struck in Kremenchuk. That brings the day's reported death toll across the country to at least 19.\n\nPresident Volodymyr Zelenskyy called the attack horrific and urged allies to take just and decisive action against Russia, including stronger sanctions. He argued that such strikes have continued since sanctions on Russian energy and certain oligarchs were lifted. European Commission President Ursula von der Leyen called the attack senseless and indiscriminate and said pressure must be brought to bear on the aggressor.\n\nThe strike came as a US-brokered humanitarian truce was in effect in the town of Oleshky in Kherson region. Moscow said the six-day truce applied only to Kherson. Ukrainian Prime Minister Sergiy Koretskyi said Russia is deliberately targeting civilians, while Moscow denies this."},
  {id:2, cat:"delhii", title:"АНУ-ын Холбооны нөөцийн сан бодлогын хүүгээ 3.75–4 хувьд хэвээр үлдээлээ", titleEn:"US Federal Reserve holds policy rate at 3.75–4 percent", time:"2 цагийн өмнө", timeEn:"2 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Eccles_Building_(26088200676).jpg?width=760", text:"АНУ-ын Холбооны нөөцийн сан (ХНС) лхагва гарагт болсон хуралдаанаараа бодлогын хүүгээ 3.75–4.00 хувийн түвшинд хэвээр үлдээх шийдвэр гаргалаа. Холбооны нээлттэй зах зээлийн хорооны 12 гишүүний 10 нь хүүг өөрчлөхгүй байхыг дэмжсэн бол хоёр гишүүн эсрэг санал өгчээ. Энэ шийдвэр нь есдүгээр сард хүүг 0.25 нэгж хувиар өсгөсний дараа гарсан бөгөөд зах зээлийн хүлээлттэй нийцэж байна.\n\nЭсрэг санал өгсөн Захирагч Лиза Күүк болон Кливлендийн Холбооны нөөцийн банкны Ерөнхийлөгч Бет Хэммак нар хүүг 0.25 нэгж хувиар нэмж өсгөхийг дэмжсэн байна. Хороо мэдэгдэлдээ эдийн засгийн идэвхжил «хүчтэй хурдаар» тэлж, дотоодын зардал тэсвэртэй, бүтээмжийн өсөлт өндөр, хөрөнгийн хөрөнгө оруулалт бат бөх байгаа ч инфляц өндөр хэвээр байна гэж дурджээ. Есдүгээр сард хэрэглээний үнийн жилийн инфляц 3.7 хувь болж, наймдугаар сарын 3.4 хувиас өссөн бол суурь инфляц 2.4 хувиас 2.6 хувь болж өссөн байна.\n\nХНС-ын дарга Кевин Уорш хэвлэлийн бага хурал дээр санхүүгийн нөхцөл байдал зарим бизнес болон өрхийн хувьд чангарч эхэлсэн ч ойрын хугацааны инфляцын зураг хэт өндөр хэвээр байгаа тул «инфляцыг бууруулах нь бидний үүрэг» гэж хэллээ. Тэрбээр мөн хорооны хуралдааны хуваарийг өөрчлөхөө мэдэгдсэн байна: 2027 онд найман хурлын долоо нь бодлогын шийдвэр гаргах хурал, нэг нь зөвхөн стратегийн асуудал хэлэлцэх хурал болох бол 2028 онд зургаа нь бодлогын, хоёр нь стратегийн хурал болно.\n\nШийдвэрийн дараа АНУ-ын хувьцааны зах зээл бага зэрэг өссөн бөгөөд худалдаачид арванхоёрдугаар сарын 8–9-ний хуралдаанаар хүү дахин өсөх магадлалыг 80 орчим хувь гэж үнэлж байна.", textEn:"The United States Federal Reserve on Wednesday left its benchmark interest rate unchanged at 3.75–4.00 percent. Ten of the 12 members of the Federal Open Market Committee voted to hold rates steady, while two voted against. The decision followed a quarter-point increase in September and was in line with market expectations.\n\nGovernor Lisa Cook and Cleveland Federal Reserve President Beth Hammack dissented, favouring a further quarter-point increase. In its statement, the committee said economic activity is expanding at a strong pace, domestic spending has been resilient, productivity growth is strong and capital investment is robust, but inflation remains elevated. Headline consumer price inflation rose to 3.7 percent year on year in September, up from 3.4 percent in August, while core inflation rose from 2.4 percent to 2.6 percent.\n\nFed Chair Kevin Warsh said at a press conference that financial conditions have begun to tighten for some businesses and households, but that with the near-term inflation picture still too high, it is the Fed's responsibility to bring inflation down. He also announced a change to the meeting calendar: in 2027, seven of the committee's eight meetings will set policy and one will focus solely on strategy, while in 2028 six will set policy and two will focus on strategy.\n\nUS stocks rose modestly after the decision, and traders were pricing roughly an 80 percent chance of another rate increase at the December 8–9 meeting."},
  {id:3, cat:"delhii", title:"Нидерландад D66 болон PVV тус бүр 26 суудал авч, эвслийн хэлэлцээ сунжрах төлөвтэй", titleEn:"Netherlands election ends in 26–26 tie between D66 and PVV", time:"3 цагийн өмнө", timeEn:"3 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Binnenhof_in_The_Hague%2C_Netherlands.jpg?width=760", text:"Нидерландын парламентын сонгуулийн санал тооллогын 90 гаруй хувь дууссаны дараа төвч үзэлт либерал D66 нам болон Герт Вилдерсийн эрх баригчдын эсрэг Эрх чөлөөний нам (PVV) тус бүр 150 суудалтай Төлөөлөгчдийн танхимд 26 суудал авч, тэнцсэн байна. Эхний exit poll-оор D66 27 суудал авч бага зэрэг тэргүүлж, PVV 25, ардчилсан либерал VVD 23, Ногоон-Хөдөлмөрийн эвсэл 20, Христэд итгэгч ардчилсан CDA 19 суудал авах төлөвтэй байсан юм.\n\nD66-ын дарга, 38 настай Роб Жеттен ялалтаа зарлаж, «Нидерланд төдийгүй дэлхий дахинд популист, хэт барууны хөдөлгөөнүүдийг ялж болохыг харууллаа» гэж хэлжээ. Тэрбээр Нидерландын хамгийн залуу бөгөөд анхны ил тод гей Ерөнхий сайд болох боломжтой гэж хэвлэлүүд бичиж байна. Харин Вилдерс суудлаа алдсандаа харамсаж байгаагаа хэлсэн ч сөрөг хүчний байр сууринаас тэмцлээ үргэлжлүүлнэ гэж мэдэгдсэн байна.\n\nСонгууль нь Схоофын Засгийн газар зургадугаар сард цагаачлал, орогнолын асуудлаар задран унасны дараа болсон ээлжит бус сонгууль юм. Сонгуулийн кампанит ажлын үеэр цагаачлал болон орогнолын төвүүдийн ачаалал гол сэдэв байсан ч сонгогчдын хувьд хамгийн чухал асуудал нь орон сууцны хомсдол байв: 18 сая хүн амтай улсад 400,000 орчим орон сууц дутагдаж байгаа бөгөөд Жеттений нам энэ хямралыг шийдвэрлэхийн тулд 10 шинэ хот барих төлөвлөгөө дэвшүүлсэн байна.\n\nОлонх бүрдүүлэхийн тулд 76 суудал шаардлагатай тул эвслийн хэлэлцээ урт үргэлжлэх төлөвтэй байна. Гол намууд Вилдерстэй хамтран ажиллахгүй гэж мэдэгдсэн тул Жеттен төв баруун VVD болон бусад намуудтай эвсэл байгуулах шаардлагатай болно. Албан ёсны дүнг Нидерландын Сонгуулийн зөвлөл ойрын өдрүүдэд зарлах юм.", textEn:"With more than 90 percent of votes counted in the Netherlands' parliamentary election, the centrist liberal D66 party and Geert Wilders' far-right Party for Freedom (PVV) are tied at 26 seats each in the 150-seat House of Representatives. The first exit poll had put D66 narrowly ahead with 27 seats, followed by the PVV with 25, the conservative liberal VVD with 23, the Green Left-Labour alliance with 20 and the Christian Democratic CDA with 19.\n\nD66 leader Rob Jetten, 38, declared victory, saying the result showed the Netherlands and the world that populist and far-right movements can be beaten. Reports note he could become the Netherlands' youngest prime minister and its first openly gay prime minister. Wilders said he regretted losing seats but pledged to continue his fight from the opposition benches.\n\nThe snap election followed the collapse of the Schoof cabinet in June over asylum and migration policy. Migration and crowded asylum centres were major campaign themes, but for many voters the most important issue was the housing shortage: with a population of 18 million, the country needs around 400,000 more homes, and Jetten's party has proposed building 10 new cities to address the crisis.\n\nA majority requires 76 seats, so coalition talks are expected to be lengthy. Mainstream parties have ruled out governing with Wilders, so Jetten will need to build a coalition with the centre-right VVD and other parties. The Dutch Electoral Council is expected to announce the official result in the coming days."},
  {id:4, cat:"delhii", title:"Израилын сонгуульд Нетаньяхугийн эвсэл тэргүүлж байгаа ч олонх бүрдүүлж чадахгүй байна", titleEn:"Netanyahu's bloc leads in Israel election but falls short of a majority", time:"4 цагийн өмнө", timeEn:"4 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Knesset_front_side_-_2022.jpg?width=760", text:"Израилын 2026 оны сонгуулийн санал тооллого үргэлжилж байгаа бөгөөд Ерөнхий сайд Биньямин Нетаньяхугийн эвсэл 53–54 орчим суудал авч тэргүүлж байгаа гэж мэдээллүүд дурдаж байна. Гэхдээ Кнессетийн 120 суудлаас олонх болохын тулд 61 суудал шаардлагатай тул аль ч эвсэл дангаараа засгийн газар байгуулж чадахгүй байгаа нь тодорхой болжээ. Сөрөг хүчний эвсэл ч мөн ойролцоо суудал авч байгаа тул эвслийн хэлэлцээ долоо хоногоор сунжрах магадлалтай байна.\n\nНетаньяху пүрэв гарагт Араб тэргүүтэй намуудын сонгуулийн луйврын талаарх мэдэгдлээ эрчимжүүлж, гадаадын оролцоо байж болзошгүйг «газар хөдлөлт» гэж нэрлэжээ. Харин сонгуулийн дээд байгууллага дотоодын аюулгүй байдлын агентлагаас энэ асуудлыг шалгахыг хүссэн байна. Ликуд нам хамгийн олон санал авсан ганц нам хэвээр байгаа ч энэ нь дангаараа засгийн газар байгуулах баталгаа болохгүй гэж ажиглагчид онцолж байна.\n\nЭнэ сонгууль нь 2023 оны аравдугаар сарын 7-ны халдлагаас хойшхи анхны улсын сонгууль бөгөөд сонгогчдын идэвх сүүлийн хэдэн арван жилийн хамгийн өндөр түвшинд хүрсэн гэж мэдээлжээ. Сонгууль нь тус улсын хамгийн удаан хугацаанд Ерөнхий сайдаар ажиллаж буй Нетаньяхугийн хувьд нэг ёсны итгэл үзүүлэлтийн санал хураалт гэж өргөнөөр харж байв.\n\nАлбан ёсны баталгаажсан дүн арваннэгдүгээр сарын 4-нд нийтлэгдэх бөгөөд түүнээс хойш Ерөнхийлөгч засгийн газар байгуулах үүргийг аль нэг намын даргад өгөх юм. Эвслийн хэлэлцээний үр дүн нь Израилын дотоод бодлого төдийгүй бүс нутгийн аюулгүй байдал, олон улсын харилцаанд нөлөөлөх тул дэлхий нийт анхааралтай ажиглаж байна.", textEn:"Vote counting continues in Israel's 2026 election, with reports putting Prime Minister Benjamin Netanyahu's bloc ahead on around 53–54 seats. However, with 61 of the Knesset's 120 seats needed for a majority, no bloc can form a government on its own, and coalition talks are expected to drag on for weeks. The opposition bloc is also projected to hold a similar number of seats.\n\nOn Thursday, Netanyahu intensified allegations of election fraud by Arab-led parties, describing suspected foreign interference as an earthquake. The top electoral body has asked the internal security agency to investigate the matter. Likud remains the largest single party, but observers note that alone does not guarantee it can form a government.\n\nThe election is the first national vote since the October 7, 2023 attack, and voter turnout was reported to be among the highest in decades. The vote was widely seen as a referendum on Netanyahu, the country's longest-serving prime minister.\n\nOfficial certified results will be published on November 4, after which the President will task a party leader with forming a government. The outcome of coalition talks will affect not only Israel's domestic politics but also regional security and international relations, so the world is watching closely."},
  {id:5, cat:"delhii", title:"НҮБ-ын Ерөнхий Ассамблей АНУ-ыг Кубын эсрэг хоригоо цуцлахыг 165 саналаар уриаллаа", titleEn:"UN General Assembly urges US to end Cuba embargo by 165 votes", time:"5 цагийн өмнө", timeEn:"5 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Shore_of_the_East_River_with_Headquarters_of_the_United_Nations%2C_New_York_City%2C_20231005_1131_2224.jpg?width=760", text:"НҮБ-ын Ерөнхий Ассамблей лхагва гарагт АНУ-ыг Кубэд ногдуулсан эдийн засаг, худалдаа, санхүүгийн хоригоо цуцлахыг уриалсан тогтоолын төслийг 165 саналаар баталлаа. Тогтоолыг эсрэг 7 орон санал өгсөн бөгөөд тэдгээр нь АНУ, Израиль, Украин, Аргентин, Унгар, Умард Македон, Парагвай байв. Харин 12 орон түдгэлзсэн байна.\n\nЭнэ тогтоол нь хууль зүйн хувьд заавал биелүүлэх үүрэг хүлээгээгүй ч олон улсын хамтын нийгэмлэгийн байр суурийг илэрхийлэх чухал дохио гэж үздэг. Ерөнхий Ассамблей жил бүр үүнтэй төстэй тогтоол баталдаг бөгөөд дэмжлэг нь тогтмол өндөр байдаг нь хоригийн асуудлаар олон улсын санал нэгдэл байгааг харуулж байна.\n\nКубын төлөөлөгчид хориг нь тус улсын эдийн засаг, эрүүл мэнд, боловсрол зэрэг салбарт хүнд дарамт учруулж байна гэж мэдэгддэг бол АНУ-ын тал хориг нь хүний эрх, ардчиллын асуудлаарх бодлогын хэрэгсэл гэж тайлбарладаг. Санал хураалтын дараа талууд байр сууриа дахин нотолсон бөгөөд ойрын хугацаанд АНУ-ын бодлогод өөрчлөлт гарах шинж тэмдэг харагдахгүй байна.\n\nСанал хураалт нь олон улсын худалдаа, хориг арга хэмжээний талаарх маргаан үргэлжилж байгаа үед болсон нь анхаарал татаж байна. Хоригийг цуцлахыг дэмжсэн орнууд хориг нь энгийн иргэдийн амьдралд сөргөөр нөлөөлж, бүс нутгийн хамтын ажиллагаанд саад болж байна гэж үзэж байна.", textEn:"The UN General Assembly on Wednesday adopted a draft resolution urging the United States to end its economic, commercial and financial embargo against Cuba, by 165 votes to seven. The countries voting against were the United States, Israel, Ukraine, Argentina, Hungary, North Macedonia and Paraguay. Twelve countries abstained.\n\nThe resolution is not legally binding, but it is seen as an important signal of the international community's position. The General Assembly adopts a similar resolution each year, and consistently high support shows broad international agreement on the embargo issue.\n\nCuban representatives say the embargo places a heavy burden on the economy, health and education, while the United States describes it as a policy tool linked to human rights and democracy. After the vote, both sides restated their positions, and there is no sign of an imminent change in US policy.\n\nThe vote came amid continuing debate over international trade and sanctions. Countries supporting an end to the embargo argue that it harms ordinary people's lives and hinders regional cooperation."},
  {id:6, cat:"delhii", title:"Луврын музейн үнэт эдлэлийн хулгайн хэрэгт хоёр сэжигтнийг албан ёсоор шалгаж эхэллээ", titleEn:"Two suspects formally investigated over Louvre jewel heist", time:"6 цагийн өмнө", timeEn:"6 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Louvre_Courtyard%2C_Looking_West.jpg?width=760", text:"Францын Парис хотын Луврын музейд саяхан гарсан үнэт эдлэлийн хулгайн хэрэгт холбогдсон байж болзошгүй хоёр эрэгтэйг албан ёсны мөрдөн шалгалтад хамруулж, цагдан хорьсон гэж Францын өргөн нэвтрүүлэгч BFMTV лхагва гарагийн орой мэдээллээ. Хоёр сэжигтэн хоёулаа 30 гаруй настай бөгөөд бямба гарагийн орой баривчлагдсан байна.\n\nПарисын прокурор Лор Беккоогийн мэдээлснээр, сэжигтнүүд хулгайд оролцсоноо «хэсэгчлэн хүлээн зөвшөөрсөн» байна. Гэхдээ хулгайлагдсан үнэт эдлэлүүд одоогоор олдоогүй хэвээр байгаа бөгөөд мөрдөн шалгах ажиллагаа үргэлжилж байна. Мөрдөн байцаагчид хулгайн гэмт хэргийг хэрхэн үйлдсэн, өөр хүмүүс оролцсон эсэхийг тогтоохоор ажиллаж байна.\n\nЛувр нь дэлхийн хамгийн алдартай музейн нэг бөгөөд тэнд гарсан хулгай нь Франц төдийгүй дэлхий дахинд шуугиан тарьсан юм. Музейн аюулгүй байдлын талаарх асуултууд дахин гарч, эрх баригчид хамгаалалтыг чангатгах арга хэмжээ авч байгаа гэж мэдээлжээ.\n\nХулгайлагдсан эдлэлүүдийг эрэн сурвалжлах ажил үргэлжилж байгаа бөгөөд цагдаа нар олон улсын хамтын ажиллагааны хүрээнд мэдээлэл солилцож байна. Сэжигтнүүдийг шүүхэд шилжүүлэх эсэх нь мөрдөн шалгалтын явцаас хамаарна.", textEn:"Two men suspected of involvement in the recent jewel heist at the Louvre Museum in Paris have been placed under formal investigation and remanded in custody, French broadcaster BFMTV reported on Wednesday evening. Both suspects are in their 30s and were detained on Saturday evening.\n\nParis Prosecutor Laure Beccuau said the suspects have partially admitted their involvement in the crime. However, the stolen jewels remain missing, and the investigation continues. Investigators are working to establish how the heist was carried out and whether other people were involved.\n\nThe Louvre is one of the world's most famous museums, and the heist caused a stir in France and around the world. Questions about museum security have resurfaced, and authorities are reported to be tightening protection measures.\n\nThe search for the stolen jewels continues, with police sharing information through international cooperation channels. Whether the suspects will be sent to trial will depend on the course of the investigation."},
  {id:7, cat:"uls-tor", title:"Японы Ерөнхий сайд Такайчи Монголын түймрийн хохирлыг сэргээхэд дэмжлэг үзүүлэхээ амлав", titleEn:"Japan PM Takaichi pledges support for Mongolia wildfire recovery", time:"7 цагийн өмнө", timeEn:"7 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Tokyo_skyline_seen_from_Tokyo_Skytree.jpg?width=760", text:"Японы Ерөнхий сайд Такайчи Санаэ пүрэв гарагт Монгол Улсын Ерөнхий сайд Н.Учралтай утсаар ярьж, Монголын зүүн нутагт гарсан томоохон түймрийн хохирлыг сэргээхэд дэмжлэг үзүүлэхээ амлав. Тэрбээр Японы Засгийн газар хохирлын цар хүрээг нухацтай авч үзэж байгаа бөгөөд Монголын ард түмэнд чин сэтгэлийн эмгэнэл илэрхийлж байна гэж хэлжээ.\n\nТакайчигийн мэдэгдсэнээр, Японы Олон улсын хамтын ажиллагааны байгууллага (JICA)-гийн ой, байгаль орчныг хамгаалах мэргэжилтнүүд мягмар гарагт Монголд илгээгдсэн байна. Тэдний тайланд үндэслэн Японы Засгийн газар шаардлагатай тоног төхөөрөмж нийлүүлэх, хүний нөөцийг хөгжүүлэх зэрэг сэргээн засварлах хамтын ажиллагааны багцыг ойрын харилцаатайгаар хэрэгжүүлэх юм.\n\nТүймэр нь аравдугаар сарын 8-нд Дорнод аймгийн дархан цаазат газарт эхэлсэн бөгөөд Японы харилцаа холбооны KDDI компанийн охин компани болох Мобикомын үйл ажиллагаатай холбоотой гэж мэдээлжээ. KDDI компани өмнө нь уучлал гуйж, Монголын эрх баригчдын мөрдөн шалгах ажиллагаанд бүрэн хамтран ажиллахаа мэдэгдсэн байна. Ерөнхий сайд Учрал хохирлын цар хүрээг тайлбарлаж, Такайчигийн эмгэнэл болон дэмжлэгийн саналд гүн талархал илэрхийлсэн гэж мэдээлжээ.\n\nМонголын Засгийн газар өмнө нь хариуцлагатай этгээдийг тогтоосны дараа нөхөн төлбөр нэхэмжлэх асуудлыг авч үзэхээ мэдэгдсэн билээ. Японы дэмжлэг нь түймэрт өртсөн экосистемийг нөхөн сэргээх, орон нутгийн иргэдийн амьжиргааг дэмжихэд чухал ач холбогдолтой гэж үзэж байна.", textEn:"Japanese Prime Minister Sanae Takaichi pledged support for the recovery of areas damaged by a huge wildfire in Mongolia during phone talks with Mongolian Prime Minister Nyam-Osor Uchral on Thursday. She said the Japanese government takes the scale of the damage seriously and extended her heartfelt sympathies to the people of Mongolia.\n\nAccording to Takaichi, experts in forestry and environmental conservation from the Japan International Cooperation Agency (JICA) were dispatched to Mongolia on Tuesday. Based on their report, the Japanese government will provide a cooperation package for the recovery of the affected areas, including the provision of necessary equipment and human resource development, while maintaining close communication with the Mongolian government.\n\nThe fire broke out on October 8 in a strictly protected area in eastern Mongolia's Dornod province and has been linked to the activities of Mobicom, the Mongolian subsidiary of Japanese telecom giant KDDI. KDDI previously offered an apology and said it would fully cooperate with Mongolian authorities' investigation. Prime Minister Uchral reportedly explained the extent of the damage and expressed deep gratitude for Takaichi's message of sympathy and offer of support.\n\nThe Mongolian government has previously said it will consider seeking compensation after identifying those responsible for the blaze. Japan's support is seen as important for restoring the fire-damaged ecosystem and supporting local residents' livelihoods."},
  {id:8, cat:"niigem", title:"Томуугийн тохиолдлын 77.1 хувийг 15 хүртэлх насны хүүхдүүд эзэлж байна", titleEn:"Children under 15 account for 77.1% of flu cases", time:"8 цагийн өмнө", timeEn:"8 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Influenza_vaccine_(2021)_A.jpg?width=760", text:"Монгол Улсад томуу болон томуу төст өвчний тархалт «Идэвхтэй» түвшинд байгаа бөгөөд мэдээлэгдсэн тохиолдлын 77.1 хувийг 15 хүртэлх насны хүүхдүүд эзэлж байна гэж Эрүүл мэндийн яам аравдугаар сарын 29-нд мэдээллээ. Энэ нь томуугийн улирал эхэлж, хүүхдүүдийн дунд халдвар эрчимтэй тархаж байгааг харуулж байна.\n\nӨмнөх мэдээллээр, аравдугаар сарын 27-ны байдлаар улсын хэмжээнд зорилтот бүлгийн 455,149 хүн улирлын томуугийн вакцинд хамрагдаж, нийт хамралт 91 хувьд хүрсэн байна. Улаанбаатар хотод хамралт 92.5 хувь, орон нутагт 88.9 хувьтай байна. Гэхдээ 1–2 насны хүүхдүүдийн вакцинжуулалтын хамралт ердөө 49.7 хувьтай байгаа нь анхаарал татаж байна.\n\nЭрүүл мэндийн байгууллагууд эцэг эхчүүдийг хүүхдээ томуугийн вакцинд хамруулж, ханиад томууны шинж тэмдэг илэрвэл гэртээ амарч, бусдад халдаахгүй байхыг зөвлөж байна. Томуугийн вирусийн идэвхжил нэмэгдэхээс өмнө вакцин хийлгэх нь хүндрэлээс сэргийлэх хамгийн үр дүнтэй арга гэж мэргэжилтнүүд онцолж байна.\n\nТомуугийн улирал ойртож байгаа энэ үед сургууль, цэцэрлэгт халдвараас сэргийлэх арга хэмжээ, агааржуулалт, гарын ариун цэврийг сахих нь чухал болж байна. Эрүүл мэндийн яам томуугийн нөхцөл байдлыг тогтмол хянаж, олон нийтэд шинэчилсэн мэдээлэл хүргэж байгаа юм.", textEn:"Influenza and influenza-like illnesses are currently at the Active level nationwide in Mongolia, and children under 15 account for 77.1 percent of all reported cases, the Health Ministry said on October 29. The figures show the flu season has begun and infections are spreading rapidly among children.\n\nAccording to earlier data, as of October 27, some 455,149 people in target groups had received the seasonal flu vaccine, bringing nationwide coverage to 91 percent. Coverage stands at 92.5 percent in Ulaanbaatar and 88.9 percent in rural provinces. However, vaccination coverage among children aged 1 to 2 is only 49.7 percent, which is a cause for concern.\n\nHealth authorities advise parents to vaccinate their children and to keep children with flu symptoms at home so they do not infect others. Experts stress that getting vaccinated before flu virus activity rises is the most effective way to prevent serious complications.\n\nAs the flu season approaches, preventive measures in schools and kindergartens, ventilation and hand hygiene are becoming especially important. The Health Ministry is monitoring the flu situation regularly and providing updated information to the public."},
  {id:9, cat:"niigem", title:"Монголын нутаг дэвсгэрийн 83 хувь нь энэ өвөл зуд болох эрсдэлтэй байна", titleEn:"83% of Mongolia's territory at risk of dzud this winter", time:"9 цагийн өмнө", timeEn:"9 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mong_winter1_-_panoramio.jpg?width=760", text:"Монгол Улсын нутаг дэвсгэрийн 83-аас дээш хувь нь энэ өвөл зуд буюу цаг агаарын эрс тэс нөхцөл байдалд өртөх ямар нэгэн түвшний эрсдэлтэй байгаа гэж Байгаль орчин, уур амьсгалын өөрчлөлтийн яам аравдугаар сарын 27-нд мэдээллээ. Зуд нь хөрс хөлдөх, зузаан цас орох, бэлчээр хүрэлцэхгүй болох зэргээс үүдэн олон тооны мал хорогдох аюултай үзэгдэл юм.\n\nСаяхны зуд болох эрсдэлийн үнэлгээгээр нийт нутаг дэвсгэрийн 26 хувь нь «маш өндөр» буюу «өндөр» эрсдэлтэй бүсэд багтаж байна. Эдгээрт баруун аймгуудаас Баян-Өлгий, Увс, Завхан, Ховд, өмнөд аймгуудаас Өмнөговь, Дундговь, төвийн аймгуудаас Архангай, Өвөрхангай багтаж байна. Монгол нь эрс тэс тивлэг уур амьсгалтай, өвөл нь урт бөгөөд хатуу ширүүн, зун нь богинохон гэдгээрээ алдартай.\n\nМалчид болон орон нутгийн удирдлагуудад өвөлжилтийн бэлтгэлийг эрт хангах, малын тэжээл, түлш, эм тариа нөөцлөх, цаг агаарын мэдээг тогтмол сонсохыг мэргэжилтнүүд зөвлөж байна. Зуд болох эрсдэл өндөр байгаа нь мал аж ахуйгаас хамааралтай олон өрхийн амьжиргаанд шууд нөлөөлж болзошгүй тул эрт сэрэмжлүүлэг, бэлтгэл онцгой чухал болж байна.\n\nБайгаль орчны яам зуд болох эрсдэлийн зураглалыг тогтмол шинэчилж, эрсдэлтэй бүс нутгуудад дэмжлэг үзүүлэх арга хэмжээг төлөвлөж байгаа юм. Өнгөрсөн жилүүдийн туршлагаас харахад эрт бэлтгэсэн айл өрхүүд малын хорогдлыг мэдэгдэхүйц бууруулж чаддаг байна.", textEn:"More than 83 percent of Mongolia's territory is at some level of risk of experiencing dzud, an extreme winter weather phenomenon, this winter, the Ministry of Environment and Climate Change said on October 27. Dzud is a Mongolian term for severe winter conditions that can cause large numbers of livestock to die because of frozen ground, deep snow or a lack of accessible pasture.\n\nA recent dzud risk assessment showed that 26 percent of the country's total territory faces a very high or high risk of dzud this winter. The areas at very high or high risk include the western provinces of Bayan-Ulgii, Uvs, Zavkhan and Khovd; the southern provinces of Umnugovi and Dundgovi; and the central provinces of Arkhangai and Uvurkhangai. Mongolia is known for its harsh continental climate, with long, bitterly cold winters and short summers.\n\nExperts advise herders and local authorities to prepare early for winter, stockpile animal fodder, fuel and medicines, and follow weather forecasts regularly. Because high dzud risk directly affects the livelihoods of many households dependent on livestock, early warning and preparation are especially important.\n\nThe environment ministry is regularly updating its dzud risk mapping and planning support measures for at-risk regions. Experience from past years shows that households that prepare early can significantly reduce livestock losses."},
  {id:10, cat:"ediin-zasag", title:"E-Mart Монголд 7 дахь дэлгүүрээ нээж, 8 дахь нь 11 дүгээр сард нээгдэнэ", titleEn:"E-Mart opens 7th store in Mongolia, with 8th set for November", time:"10 цагийн өмнө", timeEn:"10 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Supermarket%2C_Ferney-Voltaire_(EB190326).jpg?width=760", text:"Солонгосын жижиглэн худалдааны E-Mart компани Монголд 7 дахь дэлгүүрээ Улаанбаатар хотод нээж, 8 дахь дэлгүүрээ 11 дүгээр сард нээхээр төлөвлөж байна гэж Сөүлийн эдийн засгийн өдөр тутмын сонин аравдугаар сарын 29-нд мэдээллээ. Ингэснээр компани Монголын зах зээлд тэлэлтээ хурдасгаж, хоёр дэлгүүрийг ойрхон хугацаанд дараалан нээж байна.\n\nE-Mart нь Монголын хэрэглэгчдэд Солонгосын бараа бүтээгдэхүүн, хүнсний бүтээгдэхүүн болон өдөр тутмын хэрэглээний барааг санал болгодог бөгөөд Улаанбаатар хотод байр сууриа бэхжүүлж байна. Шинэ дэлгүүрүүд нь хотын худалдааны өрсөлдөөнийг нэмэгдүүлж, хэрэглэгчдэд сонголт, үнийн хувьд илүү боломж олгоно гэж салбарынхан үзэж байна.\n\nМонголын жижиглэн худалдааны зах зээл сүүлийн жилүүдэд хурдацтай өсөж, олон улсын сүлжээ дэлгүүрүүдийн сонирхлыг татаж байна. Хотжилт, дундаж давхаргын өсөлт, хэрэглэгчдийн эрэлт өөрчлөгдөж байгаа нь гадаадын жижиглэн худалдаачдад шинэ боломж нээж байгаа юм.\n\nE-Mart-ын тэлэлт нь Монгол, Солонгосын эдийн засгийн харилцаа өргөжиж байгаагийн нэг илрэл гэж үзэж байна. Цаашид компани орон нутагт ч салбараа нээх эсэх нь анхаарлын төвд байна.", textEn:"South Korean retailer E-Mart has opened its seventh store in Mongolia, in Ulaanbaatar, and plans to open its eighth store in November, the Seoul Economic Daily reported on October 29. The company is accelerating its expansion in Mongolia, opening two stores in quick succession.\n\nE-Mart offers Mongolian consumers Korean products, food and everyday goods, and is consolidating its position in Ulaanbaatar. Industry observers say the new stores will increase retail competition in the city and give consumers more choice and better prices.\n\nMongolia's retail market has grown rapidly in recent years, attracting interest from international retail chains. Urbanisation, the growth of the middle class and changing consumer demand are opening new opportunities for foreign retailers.\n\nE-Mart's expansion is seen as one sign of broadening Mongolia–South Korea economic ties. Whether the company will open stores in rural provinces in future remains a point of interest."},
  {id:11, cat:"ediin-zasag", title:"Монголын шатахууны хомсдол үргэлжилж байна: 10 дугаар сард Оросоос 78,000 тонн гэрээ байгуулжээ", titleEn:"Mongolia fuel shortage drags on as October Russian supply reaches 78,000 tonnes", time:"11 цагийн өмнө", timeEn:"11 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/HP_Petrol_Bunk_31102016.jpg?width=760", text:"Монголд шатахууны хомсдол үргэлжилж байгаа бөгөөд аравдугаар сард Оросоос 78,000 тонн шатахуун гэрээ байгуулсан нь AI-92 бензиний сарын хэрэгцээг бараг нөхөх хэмжээнд хүрч байгаа гэж «Mongolia Weekly» нийтлэлд дурджээ. Ингэснээр хомсдол нь түр зуурын саатал байхаа больж, сар бүр ижил хэмжээний шатахуун олж байх шаардлагатай тогтмол асуудал болж байна.\n\nМэдээллээр, Оросын нийлүүлэлт нэмэгдэх боломж хязгаарлагдмал байгаа бөгөөд тус улсын боловсруулах үйлдвэрүүдийн хүчин чадал нь нэмэлт хэмжээ нийлүүлэхэд хүндрэл учруулж байна. Монгол нь шатахууны хэрэгцээгээ голчлон Оросоос хангадаг тул нийлүүлэгч талын аливаа хязгаарлалт дотоодын зах зээлд шууд нөлөөлдөг.\n\nШатахууны хомсдол нь тээвэр, хөдөө аж ахуй, уул уурхай зэрэг салбарт дарамт учруулж, үнийн өсөлтөд нөлөөлж болзошгүй гэж салбарынхан анхааруулж байна. Жолооч нар шатахуун түгээх станцуудад дараалал үүсэх, зарим төрлийн шатахуун дуусах зэрэг хүндрэлтэй тулгарч байна.\n\nЭрх баригчид нийлүүлэлтийг тогтворжуулах, нөөцийг нэмэгдүүлэх, өөр эх үүсвэрээс шатахуун татах боломжийг судалж байгаа гэж мэдээлжээ. Гэхдээ ойрын хугацаанд зах зээлийн нөхцөл байдал бүрэн хэвийн болох эсэх нь тодорхойгүй хэвээр байна.", textEn:"Mongolia's fuel shortage is dragging on, with 78,000 tonnes of fuel contracted from Russia in October, barely a month's worth of AI-92 gasoline use, according to a Mongolia Weekly report. The shortage is no longer a temporary disruption: every month, the same amount of fuel must be found, and the numbers barely add up.\n\nAccording to the report, Russia cannot supply much more, as its refineries face constraints on additional volumes. Because Mongolia meets most of its fuel needs from Russia, any limitation on the supplier's side directly affects the domestic market.\n\nIndustry observers warn that the shortage puts pressure on transport, agriculture and mining and could feed into price increases. Drivers have faced queues at filling stations and shortages of some fuel types.\n\nAuthorities are reported to be working to stabilise supply, increase reserves and explore fuel from alternative sources. However, it remains unclear whether market conditions will fully normalise in the near term."},
  {id:12, cat:"ediin-zasag", title:"Сонгинохайрханд тээврийн хэрэгслийн техникийн хяналтын дэвшилтэт шугам нээгдлээ", titleEn:"Upgraded vehicle inspection line opens in Songinokhairkhan", time:"12 цагийн өмнө", timeEn:"12 hours ago", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Cars_in_a_local_mechanic_workshop_in_Nigeria.jpg?width=760", text:"Монгол Улс Сонгинохайрхан дүүргийн Техникийн хяналтын төвд тээврийн хэрэгслийн техникийн хяналтын дэвшилтэт шугамыг нээжээ. Энэ нь тээврийн хэрэгслийн техникийн хяналтын хүчин чадлыг бэхжүүлэх, замын хөдөлгөөний аюулгүй байдлыг сайжруулах, байгаль орчны бохирдлыг бууруулах зорилготой 13 сая ам.долларын төслийн нэг хэсэг юм.\n\nШинэ шугам нь тээврийн хэрэгслийг илүү нарийвчлалтай, хурдан шалгах боломж олгож, хяналтын үйл явцыг ил тод, үр дүнтэй болгоно гэж төслийн хэрэгжүүлэгчид мэдээлжээ. Техникийн хяналт нь замын ослоос сэргийлэх, техникийн гэмтэлтэй тээврийн хэрэгслийг илрүүлэхэд чухал үүрэгтэй.\n\nУлаанбаатар хотод тээврийн хэрэгслийн тоо жил бүр нэмэгдэж байгаа бөгөөд техникийн хяналтын ачаалал ч өсөж байна. Дэвшилтэт тоног төхөөрөмж нь утааны ялгаруулалтыг хэмжих, тоормос, гэрэлтүүлэг зэрэг аюулгүй байдлын үзүүлэлтүүдийг шалгахад тусална.\n\nТөслийн хүрээнд хяналтын төвийн ажилтнуудыг сургаж, үйлчилгээний чанарыг сайжруулах арга хэмжээ авч байгаа юм. Замын хөдөлгөөний аюулгүй байдал нь нийгмийн эрүүл мэнд, эдийн засагт шууд нөлөөлдөг тул энэ хөрөнгө оруулалт урт хугацаанд үр өгөөжөө өгнө гэж үзэж байна.", textEn:"Mongolia has opened an advanced vehicle technical inspection line at the Songinokhairkhan Technical Inspection Centre. It is part of a 13 million US dollar project to strengthen vehicle inspection capacity, improve road safety and reduce environmental pollution.\n\nThe new line will allow vehicles to be inspected more accurately and quickly, making the inspection process more transparent and efficient, according to the project implementers. Technical inspection plays an important role in preventing road accidents and detecting vehicles with technical defects.\n\nThe number of vehicles in Ulaanbaatar is growing every year, and the load on inspection centres is rising too. Advanced equipment will help measure exhaust emissions and check safety indicators such as brakes and lighting.\n\nUnder the project, inspection centre staff are being trained and measures are being taken to improve service quality. Because road safety directly affects public health and the economy, the investment is expected to pay off over the long term."},
  {id:13, cat:"sport", title:"Э.Даваанасан дэлхийн аваргаас хүрэл медаль хүртэж, Монголын анхны медалийг авчирлаа", titleEn:"Davaanasan wins Mongolia's first medal at World Wrestling Championships", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/FreestyleWrestling2.jpg?width=760", text:"Энх-Амарын Даваанасан Казахстан улсын Астана хотод болж буй Дэлхийн бөхийн аварга шалгаруулах тэмцээний эмэгтэйчүүдийн 76 кг жинд хүрэл медаль хүртэж, Монголын багийн анхны медалийг авчирлаа гэж МОНЦАМЭ аравдугаар сарын 29-нд мэдээллээ. Тэрбээр хүрэл медалийн төлөөх барилдаанд Оросын Мария Силинаг 11:2-оор ялсан байна.\n\nЭмэгтэйчүүдийн 76 кг жингийн тэмцээн аравдугаар сарын 27–28-нд Барыс Аренад болсон бөгөөд алтан медалийг Украины Анастасия Альпеева, мөнгөн медалийг Энэтхэгийн Кажал Дхочак хүртсэн бол хоёр дахь хүрэл медалийг АНУ-ын Даймонд Гилфорд авчээ. Даваанасан нь Азийн аварга бөгөөд дэлхийн аваргын мөнгөн медальт туршлагатай бөх юм.\n\nДэлхийн аварга шалгаруулах тэмцээн аравдугаар сарын 24-нөөс 11 дүгээр сарын 1-нийг хүртэл Астана хотод болж байгаа бөгөөд 135 орны 900 орчим тамирчин эрэгтэй чөлөөт, сонгомол болон эмэгтэйчүүдийн төрөлд 30 багц медалийн төлөө өрсөлдөж байна. Тэмцээнийг Дэлхийн бөхийн нэгдсэн холбоо (UWW) зохион байгуулж байна.\n\nМонголын бөхийн баг цаашид бусад жинд медалийн төлөө өрсөлдөх бөгөөд Даваанасаны хүрэл медаль нь багийнханд урам зориг өгч байна гэж дасгалжуулагчид онцолжээ. Монголын бөх сонирхогчид Астанагаас ирэх дараагийн мэдээг анхааралтай хүлээж байна.", textEn:"Enkh-Amaryn Davaanasan claimed Mongolia's first medal at the World Wrestling Championships in Astana, Kazakhstan, winning bronze in the women's 76 kg category, MONTSAME reported on October 29. She defeated Russia's Mariia Silina 11–2 in the bronze-medal contest.\n\nThe women's 76 kg competition took place on October 27–28 at Barys Arena. Gold went to Anastasiya Alpyeyeva of Ukraine and silver to Kajal Dhochak of India, while the second bronze medal went to Dymond Guilford of the United States. Davaanasan is an Asian champion and a former World Championships silver medallist.\n\nThe World Championships run from October 24 to November 1 in Astana, with around 900 athletes from 135 countries competing for 30 sets of medals in men's freestyle, Greco-Roman and women's wrestling. The event is organised by United World Wrestling (UWW).\n\nMongolia's wrestling team will continue to compete for medals in other weight classes, and coaches say Davaanasan's bronze will inspire her teammates. Mongolian wrestling fans are eagerly awaiting further news from Astana."},
  {id:14, cat:"sport", title:"Монголын пара гар барилдааны тамирчид Дэлхийн цомоос 7 медаль хүртлээ", titleEn:"Mongolian para-armwrestlers win seven medals at World Cup", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Cosmania_I_-_Arm_Wrestling_Challenge.jpg?width=760", text:"Монголын пара гар барилдааны тамирчид Узбекистан улсын Ташкент хотод болсон Пара гар барилдааны Дэлхийн цомын тэмцээнээс нийт 7 медаль хүртлээ гэж МОНЦАМЭ мэдээллээ. Энэ амжилт нь Монголын пара спортын тамирчдын олон улсын тавцанд гаргаж буй тогтвортой амжилтын нэг илрэл болж байна.\n\nГар барилдаан нь хүч, техник, тэсвэр тэвчээрийг хослуулсан спорт бөгөөд пара тамирчдын хувьд ангилал тус бүрээр өрсөлдөөн ширүүн өрнөдөг. Ташкентийн тэмцээнд дэлхийн олон орны шилдэг тамирчид оролцсон бөгөөд Монголын баг медалийн тоогоороо онцгойрч чаджээ.\n\nМонголын пара спортын тамирчид сүүлийн жилүүдэд Азийн пара наадам болон дэлхийн тэмцээнүүдэд тогтмол амжилт гаргаж, туршлага хуримтлуулж байна. Саяхан Айчи—Нагоягийн Азийн пара наадамд Монголын баг 4 алтан медаль хүртэж, түүхэн амжилт үзүүлсэн билээ.\n\nПара гар барилдааны тамирчдын амжилт нь дасгалжуулагчдын хөдөлмөр, гэр бүл болон дэмжигчдийн дэмжлэгийн үр дүн гэж спортын мэргэжилтнүүд онцолж байна. Цаашид Монголын пара тамирчид олон улсын тэмцээнүүдэд улам их амжилт гаргах боломжтой гэж үзэж байна.", textEn:"Mongolian para-armwrestlers won seven medals at the Para-Armwrestling World Cup held in Tashkent, Uzbekistan, MONTSAME reported. The result is another sign of the steady international success of Mongolia's para athletes.\n\nArmwrestling combines strength, technique and endurance, and competition in each para category is fierce. The Tashkent event brought together top athletes from many countries, and the Mongolian team stood out for its medal haul.\n\nMongolian para athletes have been performing consistently at Asian Para Games and world events in recent years, gaining valuable experience. At the recent Aichi-Nagoya Asian Para Games, Mongolia's team won four gold medals in a historic result.\n\nSports experts say the para-armwrestlers' success reflects the hard work of coaches and the support of families and fans. Mongolia's para athletes are seen as capable of even greater success at future international events."},
  {id:15, cat:"sport", title:"Энэтхэг—Шинэ Зеландын дөрөв дэх Т20 тоглолт өнөөдөр Оклендэд болно", titleEn:"India face New Zealand in fourth T20I in Auckland today", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Eden_Park_at_Dusk%2C_2013%2C_cropped.jpg?width=760", text:"Энэтхэг болон Шинэ Зеландын шигшээ багуудын таван тоглолттой Т20 цувралын дөрөв дэх тоглолт өнөөдөр буюу аравдугаар сарын 30-нд Окленд хотын Иден Парк цэнгэлдэхэд болно. Энэтхэгийн баг цувралын эхний гурван тоглолтод ялалт байгуулсан тул цувралд тэргүүлж байна.\n\nТ20 крикет нь хурдан өрнөлтэй, үзэгчдийн сонирхлыг их татдаг формат бөгөөд Иден Парк нь Шинэ Зеландын хамгийн алдартай цэнгэлдэхүүдийн нэг юм. Талбайн эзэн Шинэ Зеландын баг өөрийн талбайдаа цувралыг эргүүлэхээр тэмцэх бол Энэтхэгийн баг цувралын ялалтаа эрт баталгаажуулахыг зорьж байна.\n\nЦувралын өмнөх тоглолтуудад Энэтхэгийн цохигчид болон бөмбөг шидэгчид тогтвортой сайн тоглолт үзүүлсэн бол Шинэ Зеландын баг шийдвэрлэх мөчүүдэд алдаа гаргасан гэж шинжээчид дүгнэж байна. Дөрөв дэх тоглолт нь цувралын хувь заяаг шийдэх чухал тоглолт болно.\n\nХоёр багийн хөгжөөн дэмжигчид Оклендэд болон дэлгэцийн өмнө тоглолтыг анхааралтай хүлээж байна. Т20 цувралын дараа хоёр баг цаашид олон улсын хуваарийн дагуу бусад тэмцээнүүдэд оролцох юм.", textEn:"The fourth match of the five-match T20I series between India and New Zealand will be played today, October 30, at Eden Park in Auckland. India has won three matches in the series so far and leads the contest.\n\nT20 cricket is a fast-paced format that draws large audiences, and Eden Park is one of New Zealand's most famous stadiums. Hosts New Zealand will look to turn the series around on home soil, while India will aim to seal the series early.\n\nAnalysts say India's batters and bowlers have performed consistently in the earlier matches, while New Zealand have made errors at decisive moments. The fourth match will therefore be crucial for the fate of the series.\n\nFans of both teams in Auckland and watching on screens are eagerly awaiting the match. After the T20I series, both teams will move on to other fixtures in the international calendar."},
  {id:16, cat:"soyol", title:"Евровидение 2027 тэмцээнд 36 орон оролцохоо баталгаажууллаа", titleEn:"36 countries confirmed for Eurovision Song Contest 2027", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Alyona_alyona_and_Jerry_Heil%2C_final%2C%2C_Eurovision_2024_08.jpg?width=760", text:"Европын өргөн нэвтрүүлгийн холбоо (EBU) ирэх 2027 оны 5 дугаар сард Болгарын Бургас хотод болох Евровидение дууны тэмцээнд нийт 36 орон оролцохоо баталгаажууллаа гэж мэдээллээ. Оролцогч орнуудын бүрэн жагсаалтыг холбоо зарласан байна.\n\nЕвровидение нь Европын хамгийн том, хамгийн удаан хугацаанд үргэлжилж буй дууны тэмцээнүүдийн нэг бөгөөд жил бүр олон арван сая үзэгчдийг татдаг. Тэмцээн нь шинэ уран бүтээлчдийг нээж, улс орнуудын соёлын солилцоог дэмжих талбар болдог.\n\n2027 оны тэмцээнийг Бургас хотод зохион байгуулах нь Болгарын хувьд томоохон үйл явдал бөгөөд хотын аялал жуулчлал, эдийн засагт эерэг нөлөө үзүүлнэ гэж үзэж байна. Зохион байгуулагчид тайз, гэрэлтүүлэг, шууд дамжуулалтын бэлтгэлийг эртнээс хангаж байна.\n\nОролцогч орнууд одоо үндэсний шалгаруулалтаа явуулж, тэмцээнд оролцох дуу, уран бүтээлчдээ тодруулах юм. Евровидениегийн шүтэн бишрэгчид ирэх жилийн тэмцээний дуунуудыг сонсохыг тэсэн ядан хүлээж байна.", textEn:"The European Broadcasting Union (EBU) has confirmed that 36 countries will take part in the Eurovision Song Contest 2027, to be held next May in Burgas, Bulgaria. The union has announced the full list of competing countries.\n\nEurovision is one of Europe's largest and longest-running song contests, attracting tens of millions of viewers each year. It serves as a platform for discovering new artists and promoting cultural exchange between countries.\n\nHosting the 2027 contest in Burgas is a major event for Bulgaria and is expected to benefit the city's tourism and economy. Organisers are already preparing the stage, lighting and live broadcast arrangements.\n\nParticipating countries will now hold national selections to choose their songs and artists. Eurovision fans are eagerly awaiting next year's entries."},
  {id:17, cat:"tech", title:"Энэтхэг NVS-03 навигацийн хиймэл дагуулаа 10 дугаар сарын 30-нд хөөргөнө", titleEn:"India to launch NVS-03 navigation satellite on October 30", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/GSLV_MK2_L40_booster.jpg?width=760", text:"Энэтхэгийн Сансрын судалгааны байгууллага (ISRO) NVS-03 навигацийн хиймэл дагуулаа аравдугаар сарын 30-нд, орон нутгийн цагаар 23:51 цагт Андхра Прадеш мужийн Шрихарикота дахь Сатиш Дхаван сансрын төвөөс GSLV-F18 пуужингаар хөөргөхөөр төлөвлөж байна. Энэ нь GSLV пуужингийн 20 дахь нислэг болно.\n\nNVS-03 нь хоёр дахь үеийн NavIC навигацийн системйн гурав дахь хиймэл дагуул бөгөөд ойролцоогоор 2,250 кг жинтэй, геосинхрон шилжилтийн тойрог замд байрлуулагдана. Хиймэл дагуул нь Энэтхэгийн дотооддоо бүтээсэн атомын цаг болон худалдан авсан атомын цагнуудыг тээх бөгөөд L1 давтамжийн зурвасыг нэмж ашигласнаар ухаалаг утас, автомашины навигаци, зүүдэг төхөөрөмжүүдэд NavIC мэдээллийг саадгүй нэгтгэх боломжтой болно.\n\nNavIC систем нь Энэтхэгийн нутаг дэвсгэр болон түүнээс 1,500 км орчмын бүс нутагт байрлал, навигаци, цаг хугацааны үнэн зөв үйлчилгээ үзүүлэх зорилготой. Өмнөх NVS-02 хиймэл дагуул өнгөрсөн онд тойрог замд амжилттай орсон ч зорилтот геостационар тойрог замд хүрэхэд шаардлагатай тойрог замын маневрыг хийж чадаагүй юм. NVS-03-ын хөөргөлтийг дээд зөвлөлийн зөвлөмжийн дагуу засвар хийсний дараа төлөвлөжээ.\n\nСансрын сайдын парламентын хариултаар, 7 дугаар сарын байдлаар NavIC-ийн зөвхөн гурван хиймэл дагуул навигацийн үйлчилгээ үзүүлж байсан бөгөөд бие даасан байрлал тогтоохын тулд дор хаяж дөрвөн хиймэл дагуул шаардлагатай байна. NVS-03 амжилттай ашиглалтад орвол NavIC-ийн навигацийн флот дөрөв болж, үндсэн босго хэмжээнд хүрэх юм. ISRO нийт таван хоёр дахь үеийн NavIC хиймэл дагуул төлөвлөж байна.", textEn:"The Indian Space Research Organisation (ISRO) plans to launch its NVS-03 navigation satellite on October 30 at 11:51 p.m. local time from the Satish Dhawan Space Centre at Sriharikota, Andhra Pradesh, aboard a GSLV-F18 rocket. It will be the 20th flight of the GSLV vehicle.\n\nNVS-03 is the third satellite in the second-generation NavIC navigation system, weighs around 2,250 kg and will be placed in a Geosynchronous Transfer Orbit. It carries an indigenous atomic clock alongside procured atomic clocks, and its additional L1 frequency band will allow NavIC data to be integrated seamlessly into mainstream consumer electronics, including smartphones, automotive navigation units and wearable devices.\n\nThe NavIC system is designed to provide accurate position, navigation and timing services across India and a region extending about 1,500 km beyond the country's landmass. The previous NVS-02 satellite reached orbit last year but could not carry out the orbital manoeuvres needed to reach its intended geostationary orbit. The NVS-03 launch was planned after corrective measures recommended by an apex committee.\n\nAccording to the space minister's parliamentary reply, as of July only three NavIC satellites were providing navigation services, while at least four are required for standalone positioning. If NVS-03 is successfully commissioned, the NavIC navigation fleet will reach four, meeting the basic threshold. ISRO has planned five second-generation NavIC satellites in total."},
  {id:18, cat:"oron-nutag", region:"dornod", title:"Нөмрөгийн түймрийн хохирлыг үнэлэх ажлын хэсэг хоёр нисдэг тэргээр ажиллаж байна", titleEn:"Damage assessment team surveys Nomrog fire area by helicopter", time:"Өчигдөр", timeEn:"Yesterday", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Fires_in_Kazakhstan_(15035).jpg?width=760", text:"Дорнод аймгийн Халхгол сумын нутагт орших Нөмрөгийн дархан цаазат газарт гарсан түймрийн хохирлыг үнэлэх тусгай ажлын хэсэг газар дээр нь ажиллаж байна. Ажлын хэсэгт шүүх шинжилгээний мэргэжилтнүүд, ой, ургамал судлалын мэргэжилтнүүд багтсан бөгөөд шаардлагатай тоног төхөөрөмж, эрчим хүчний хангамжийг зохион байгуулж, хоёр нисдэг тэргээр тогтоосон цэгүүдэд үнэлгээ хийж байна.\n\nХиймэл дагуулын зураглалаар түймэрт өртсөн нийт талбай 504,960.4 га болсон нь тогтоогдсон бөгөөд үүнээс дархан цаазат газрын 587,744.1 га талбайн 448,993.6 га буюу 76.4 хувь нь шатсан байна. Дархан цаазат газрын хилээс гадна 55,966.8 га талбай мөн түймэрт өртжээ. Эдгээр тоо баримт нь нөхөн сэргээх ажлын цар хүрээг тодорхойлоход чухал ач холбогдолтой.\n\nМонголын Засгийн газар хариуцлагатай этгээдийг тогтоосны дараа нөхөн төлбөр нэхэмжлэх асуудлыг авч үзэхээ мэдэгдсэн бөгөөд Шадар сайд Н.Номтойбаярыг «уучлал гуйх нь хангалтгүй» гэж хэлсэн гэж мэдээлжээ. Харин KDDI компани ажилтнууд нь Монголын хууль тогтоомжийг зөрчөөгүй гэж мэдэгдэж, мөрдөн шалгах ажиллагаанд бүрэн хамтран ажиллахаа илэрхийлсэн байна.\n\nТүймэр нь аравдугаар сарын 8-нд эхэлж, 12-нд хяналтад орж, 16-нд бүрэн унтраагдсан байна. Түймрийг унтраахад Монгол талаас 606 хүн, 100 гаруй техник хэрэгсэл бүхий 60 бүлэг ажилласан бол Хятадын талаас хилийн дагуу 3,400 гаруй гал сөнөөгч ажилласан гэж мэдээлжээ. Одоо анхаарал нь экосистемийг нөхөн сэргээх, зэрлэг амьтдын хохирлыг үнэлэхэд чиглэж байна.", textEn:"A specialised working group is on the ground assessing the damage from the wildfire in the Nomrog strictly protected area in Khalkhgol soum, Dornod province. The team includes forensic experts and specialists in forestry and plant research, and has organised the necessary equipment and power supply to conduct assessments at designated locations using two helicopters.\n\nSatellite mapping put the total area affected by the fire at 504,960.4 hectares, including 448,993.6 hectares, or 76.4 percent, of the protected area's 587,744.1 hectares. A further 55,966.8 hectares outside the protected area boundary also burned. These figures are important in defining the scale of restoration work.\n\nThe Mongolian government has said it will consider seeking compensation after identifying those responsible, and Deputy Prime Minister Nomtoibayar was quoted as saying that words of apology are not enough. KDDI, meanwhile, has said its employees did not violate Mongolian laws and that it will fully cooperate with the investigation.\n\nThe fire broke out on October 8, was brought under control on October 12 and was fully extinguished on October 16. Mongolia mobilised 606 personnel and more than 100 pieces of equipment in 60 firefighting groups, while China deployed more than 3,400 firefighters along its frontier, according to reports. Attention is now turning to restoring the ecosystem and assessing wildlife losses."}
];
function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-10-30", items:[
  {code:"USD", mnt:3599.08, chg:0}, {code:"EUR", mnt:4010.63, chg:0}, {code:"JPY", mnt:22.55, chg:0},
  {code:"CNY", mnt:540.29, chg:0}, {code:"KRW", mnt:2.56, chg:0}, {code:"RUB", mnt:38.76, chg:0}, {code:"GBP", mnt:4776.00, chg:0}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-7, code:1},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:20, code:1},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:15, code:0},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:16, code:0},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:5, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

